styl:
.brad-full { border-radius: 32px !important; }
.white-bg { background-color: #fff; }
.middle-title { font-family: Helvetica !important;
  font-weight: 700;
  font-size: 32px;
  line-height: 42px;
  color: #393a44;
  vertical-align: middle; }
@media screen and (max-width: 600px) {
  .middle-title { font-size: 28px !important;
    line-height: 34px !important; }
}
.text { font-family: Helvetica !important;
  font-size: 18px;
  color: #393a44;
  letter-spacing: 0;
  line-height: 26px;
  font-weight: 400; }
.text.bold { font-weight: 700; }
.pb32 { padding-bottom: 32px; }
.pb44 { padding-bottom: 44px; }
.pt44 { padding-top: 44px; }
.h-12 { font-size: 8px;
  line-height: 12px;
  height: 12px; }
.left-block { display: inline-block;
  width: 220px !important;
  vertical-align: top;
  background: #f9f9f9;
  border-radius: 24px;
  margin: 0 10px 0 0; }
@media screen and (max-width: 600px) {
  .left-block { float: none !important;
    display: block !important;
    margin: 0 auto 12px !important; }
}
.pd24 { padding: 24px 24px 26px 24px; }
.pd24-2 { padding: 24px 24px 0 24px; }
.right-block { display: inline-block;
  width: 220px !important;
  vertical-align: top;
  text-align: right;
  background: #f9f9f9;
  border-radius: 24px; }
@media screen and (max-width: 600px) {
  .right-block { float: none !important;
    display: block !important;
    width: 100% !important;
    margin: 0 auto !important; }
}
@media screen and (max-width: 600px) {
  .text.mob-text,
  .grey-text.mob-text { font-size: 17px !important; }
}
